# Fıkıh Dirâsesi — on ikinci kısım: ince kalan bablar (kazâ ve şahitlik, siyer, yeminler, ferâiz, kurban ve yiyecekler, hadler)
from urllib.parse import quote
def A(et,ref,ac): return ('ayet',et,'./#'+ref,ac)
def H(et,q,ac,kap='sitte'): return ('hadis',et,'hadis.html#ara='+quote(q)+'&kap='+kap,ac)
def m(id,yol,baslik,ar,hanefi,maliki,safii,hanbeli,sebep,delil,usul,metin):
    return dict(id=id,yol=yol,baslik=baslik,ar=ar,hanefi=hanefi,mez=dict(maliki=list(maliki),safii=list(safii),hanbeli=list(hanbeli)),sebep=sebep,delil=delil,usul=usul,metin=metin)
KZ=['Dava ve şahitlik','Dava ve şahitlik'];SY=['Siyer ve cihad','Cihad ve barış'];YM=['Yeminler','Yemin'];FR=['Ferâiz','Miras']
KB=['Kurban ve av','Kurban'];YY=['Kurban ve av','Yiyecekler'];HD=['Cinâyât ve hadler','Kısas ve hadler']
M=[
# ——— Dava ve şahitlik ———
m('sahadetfer',KZ,'Şahitlik üzerine şahitlik (şehâdet ale’ş-şehâde)','الشهادة على الشهادة',
 'Had ve kısas dışındaki bütün haklarda caizdir. Asıl şahidin ölmüş, ağır hasta ya da üç günlük yol uzaklıkta olması gibi bir mazereti bulunmalıdır. Her asıl şahidin şahitliğini iki şahit nakleder; aynı iki kişi iki asıl şahidin ikisi için de şahitlik edebilir.',
 ['Hadlerde de caiz','Mazeret şartıyla bütün haklarda, had cezalarında da kabul edilir.'],['Had ve kısasta kabul edilmez','Mal ve kul haklarında caizdir.'],['Hadlerde kabul edilmez','Mal ve kul haklarında caizdir; kısasta da kabul edilir.'],
 'Fer‘ şahit, asıl şahidin sözünü naklettiği için onun yerine geçer; ancak nakilde şüphe ihtimali artar. Hadler şüphe ile düştüğünden çoğunluk onları bu yolla ispatı kabul etmemiştir. İhtiyaç ise kul haklarının kaybolmaması için bu yolu zorunlu kılar.',
 [A('Bakara 2:282','2-282','“Erkeklerinizden iki şahidi şahit tutun.”'),A('Talâk 65:2','65-2','“İçinizden adalet sahibi iki kişiyi şahit tutun, şahitliği Allah için dosdoğru yapın.”')],
 'Hadler şüphelerle düşer (el-hudûdu tedrau bi’ş-şubühât); haklar ise ihtiyaç sebebiyle korunur.',
 [('kuduri','الشهادة على الشهادة'),('bidaye','الشهادة')]),
m('fasiksahit',KZ,'Fâsığın şahitliği','شهادة الفاسق',
 'Kadı fâsığın şahitliğini kabul etmemelidir. Ancak kabul edip onunla hükmederse hüküm geçerlidir (nâfiz); çünkü fâsık da şahitlik ehlidir, eksik olan güvenilirliğidir.',
 ['Kabul edilmez','Adalet şahitliğin şartıdır; fâsığın şahitliğiyle verilen hüküm bozulur.'],['Kabul edilmez','Adalet şarttır; hüküm geçersizdir.'],['Kabul edilmez','Adalet şarttır; tövbe edip hâli düzelirse kabul edilir.'],
 'Âyet fâsığın haberinin araştırılmasını emreder; reddedilmesini kesin olarak emretmez. Hanefîler bunu “ehliyet var, güven eksik” şeklinde anlamış, cumhur ise adaleti şahitliğin geçerlilik şartı saymıştır.',
 [A('Hucurât 49:6','49-6','“Ey iman edenler! Bir fâsık size bir haber getirirse, onu iyice araştırın.”'),A('Talâk 65:2','65-2','“İçinizden adalet sahibi iki kişiyi şahit tutun.”')],
 'Bir vasfın şart (rükün) mı yoksa kemâl sıfatı mı olduğu tartışması: şart ise yokluğu hükmü iptal eder, kemâl sıfatı ise yalnız mekruh kılar.',
 [('kuduri','الفاسق'),('bidaye','العدالة')]),
m('zimmisahit',KZ,'Gayrimüslimlerin birbirleri hakkındaki şahitliği','شهادة أهل الذمة بعضهم على بعض',
 'Zimmîlerin birbirleri lehinde ve aleyhinde şahitliği kabul edilir; dinleri farklı olsa da (yahudinin hristiyan aleyhine şahitliği gibi). Müslüman aleyhine şahitlikleri kabul edilmez.',
 ['Kabul edilmez','Hiçbir durumda gayrimüslimin şahitliği kabul edilmez.'],['Kabul edilmez','Adalet şartı bulunmadığından reddedilir.'],['Kabul edilmez','Yalnız yolculukta, Müslüman bulunmadığında vasiyet hakkında Ehl-i kitabın şahitliği kabul edilir.'],
 'Şahitlikte adalet ve İslam şart koşulunca gayrimüslimin şahitliği reddedilir. Hanefîler ise velâyeti esas almıştır: gayrimüslim kendi aralarında velâyet ehlidir, öyleyse birbirleri hakkında şahitlik de edebilir. Hanbelîler Mâide sûresindeki yolculuk âyetini zâhiriyle uygulamıştır.',
 [A('Mâide 5:106','5-106','“Ey iman edenler! Birinize ölüm gelince, vasiyet sırasında aranızdan adalet sahibi iki kişi ya da yolculukta iseniz sizden olmayan iki kişi şahitlik etsin.”'),H('Peygamber Ehl-i kitabın birbirleri hakkındaki şahitliğini caiz gördü','اجاز شهاده اهل الكتاب بعضهم','İbn Mâce.')],
 'Velâyete kıyas: kendi aralarında velâyet sahibi olan, birbirleri hakkında şahitlik de edebilir.',
 [('kuduri','الذمة'),('bidaye','الكافر')]),
m('gaibhukum',KZ,'Hazır olmayan kişi aleyhine hüküm (kazâ ale’l-gâib)','القضاء على الغائب',
 'Davalı ya da onun yerine geçen biri (vekil, vasi) mahkemede bulunmadıkça aleyhine hüküm verilmez. Çünkü hüküm, iki tarafın dinlenmesiyle verilir ve gaip olanın savunma hakkı vardır.',
 ['Caizdir','Beyyine ile gaip aleyhine hükmedilir; gaibe döndüğünde savunma hakkı tanınır.'],['Caizdir','Delil ile hükmedilir; gaip dönünce itiraz edebilir.'],['Caizdir','Davacının beyyinesi ve yeminiyle hükmedilir.'],
 'Peygamber Hind’e, kocası Ebû Süfyân hazır değilken nafakayı onun malından almasına izin vermiştir. Cumhur bunu gaip aleyhine bir hüküm saymış, Hanefîler ise bunun bir fetva olduğunu söylemiştir. Ayrıca Hz. Ali’ye “İki taraftan birini dinleyip diğerini dinlemeden hüküm verme” buyurulmuştur.',
 [H('Hind’e: “Sana ve çocuğuna yetecek kadarını örfe göre al”','خذي ما يكفيك وولدك بالمعروف','Buhârî, Müslim.')],
 'Bir sünnetin hüküm mü (kazâ) yoksa fetva mı (diyânet) olduğu ayrımı; savunma hakkının hükmün şartı olup olmadığı.',
 [('kuduri','الغائب'),('bidaye','الغائب')]),
m('kadigazap',KZ,'Hâkimin öfkeli iken hüküm vermesi','قضاء القاضي وهو غضبان',
 'Hâkim öfkeli, aç, çok yorgun ya da aklını meşgul eden bir durumda iken hüküm vermemelidir; mekruhtur. Bu hâlde verdiği hüküm doğruysa geçerlidir.',
 ['Mekruh','Hüküm doğruysa geçerlidir.'],['Mekruh','Öfkenin aklı karıştırdığı her durum buna kıyaslanır; hüküm geçerlidir.'],['Hükmetmemeli','Bazılarına göre haramdır; isabetli hüküm yine geçerlidir.'],
 'Hadis öfkeyi açıkça yasaklar. Âlimler illetin “düşünceyi karıştırması” olduğunu söyleyerek aşırı açlık, susuzluk ve kederi de ona katmıştır. Yasağın haram mı mekruh mu olduğu, hükmün geçerliliğini etkileyip etkilemediği tartışılmıştır.',
 [H('“Hâkim öfkeli iken iki kişi arasında hüküm vermesin”','لا يقضين حكم بين اثنين وهو غضبان','Buhârî, Müslim.')],
 'İllet ile kıyas: nasta geçen öfke, aklı meşgul eden her şeye genişletilir (tenkîhu’l-menât).',
 [('kuduri','غضبان'),('bidaye','غضبان')]),
m('kadihediye',KZ,'Hâkimin hediye kabul etmesi','هدية القاضي',
 'Hâkim, davası olan kimseden ve kadılıktan önce kendisiyle hediyeleşmeyen kimseden hediye kabul edemez. Yakın akrabası ve önceden hediyeleştiği kimse, davası yoksa ve hediyesini artırmamışsa bunun dışındadır. Davetlerde de yalnız genel davete katılır.',
 ['Kabul edemez','Davası olsun olmasın, görevi sebebiyle verilen hediyeyi alamaz.'],['Kabul edemez','Görevi sebebiyle verilen hediye rüşvet hükmündedir; alırsa beytülmâle verilir.'],['Kabul edemez','Önceden hediyeleştiği kişiden davası yoksa alabilir; ama almaması daha iyidir.'],
 'Görev sebebiyle verilen hediye, hükmü etkileme ihtimali taşıdığından rüşvete benzer. Peygamber zekât memurunun “Bu bana hediye edildi” demesini kınamıştır. İhtilaf, önceden var olan hediyeleşmenin istisna edilip edilmeyeceğindedir.',
 [H('“Memurların aldığı hediyeler hıyanettir”','هدايا العمال غلول','Ahmed b. Hanbel.',kap='tisa')],
 'Sedd-i zerâi: haramın (rüşvet) yolunu kapatmak için ona götüren mubah görünüşlü şey de yasaklanır.',
 [('kuduri','الهدية'),('bidaye','القاضي')]),
# ——— Siyer ve cihad ———
m('seleb',SY,'Öldürülen düşmanın üzerindeki eşya (seleb)','السلب للقاتل',
 'Seleb, imam savaştan önce “Kim bir düşman öldürürse selebi onundur” demedikçe ganimetin bir parçasıdır ve taksime girer. İmam böyle söylemişse öldürene aittir (nefl).',
 ['İmamın sözüne bağlı','Nefl olarak verilir; humustan karşılanır.'],['Öldürene aittir','İmam söylemese de öldüren, şahidi varsa selebi alır.'],['Öldürene aittir','İmamın söylemesi şart değildir; humus alınmaz.'],
 'Hadisin genel bir şer‘î hüküm mü yoksa Peygamber’in imam sıfatıyla verdiği bir karar mı (tasarruf bi’l-imâme) olduğu tartışılmıştır. Hanefî ve Mâlikîler ikincisini, Şâfiî ve Hanbelîler birincisini esas almıştır.',
 [H('“Kim bir düşman öldürür ve buna delili olursa onun selebi kendisinindir”','من قتل قتيلا له عليه بينه فله سلبه','Buhârî, Müslim.'),A('Enfâl 8:41','8-41','“Bilin ki ganimet olarak aldığınız şeyin beşte biri Allah’a, Peygamber’e, akrabaya, yetimlere, yoksullara ve yolcuya aittir.”')],
 'Peygamber’in tasarruflarının ayrılması: tebliğ (genel hüküm) ile imamet (yönetim kararı) farklı sonuç doğurur.',
 [('kuduri','السلب'),('bidaye','السلب')]),
m('humus',SY,'Ganimetin beşte birinin (humus) taksimi','قسمة الخمس',
 'Peygamber’in vefatıyla onun payı düşmüştür; akrabanın payı da yalnız fakir olanlarına verilir. Humus üç sınıfa taksim edilir: yetimler, yoksullar ve yolcular.',
 ['İmamın takdirine bırakılır','İmam humusu maslahata göre harcar; akrabaya da ihtiyaçlarına göre verir.'],['Beş kısma','Peygamber payı Müslümanların maslahatlarına; akraba payı Hâşimoğulları ile Muttaliboğullarına, zengin olsalar da verilir.'],['Beş kısma','Şâfiî gibi; akraba payı onların zengin ve fakirine verilir.'],
 'Âyet altı sınıf sayar. Allah’ın adının teberrük için mi anıldığı, Peygamber payının vefatından sonra kime geçeceği ve akraba payının yakınlığa mı yoksa ihtiyaca mı bağlı olduğu ihtilafın kaynağıdır. Hanefîler Hulefâ-yi Râşidîn uygulamasını delil getirmiştir.',
 [A('Enfâl 8:41','8-41','“Bilin ki ganimet olarak aldığınız şeyin beşte biri Allah’a, Peygamber’e, akrabaya, yetimlere, yoksullara ve yolcuya aittir.”')],
 'Hükmün illeti: akraba payı nusrete (yardım) mi yoksa ihtiyaca mı bağlıdır? İllet değişince hükmün kapsamı da değişir.',
 [('kuduri','الخمس'),('bidaye','الخمس')]),
m('ganimetyer',SY,'Ganimetin düşman topraklarında taksimi','قسمة الغنيمة في دار الحرب',
 'Ganimet dârülharpte taksim edilmez; dârülislâma getirildikten sonra taksim edilir. Çünkü mülkiyet, ganimetin İslam topraklarına ulaşmasıyla (ihrâz) tam olur.',
 ['Caizdir','Hatta savaş yerinde taksim etmek sünnettir.'],['Caizdir','Ganimet ele geçirilmekle mülk olur; savaş yerinde taksim edilebilir.'],['Caizdir','Dârülharpte taksim edilebilir; bekletmek gerekmez.'],
 'Peygamber Huneyn ganimetini Ci‘râne’de taksim etmiştir. Cumhur bunu savaş bölgesinde taksime delil saymıştır. Hanefîler Mekke’nin fethedilmiş, dolayısıyla İslam toprağı olduğunu söyleyerek bunun kendi görüşlerine aykırı olmadığını belirtmiştir.',
 [H('Peygamber Ci‘râne’de ganimetleri taksim ediyordu','يقسم التبر والغنايم','İbn Mâce.')],
 'Mülkiyetin ne zaman tamamlandığı (istîlâ mı, ihrâz mı) tartışması.',
 [('kuduri','الغنيمة'),('bidaye','الغنيمة')]),
m('kadinganimet',SY,'Kadın, çocuk ve kölenin ganimetteki hakkı','الرضخ للنساء والصبيان',
 'Savaşa katılan kadın, çocuk, köle ve zimmîye ganimetten tam pay (sehm) verilmez; imamın takdir ettiği bir bahşiş (radh) verilir. Kadınlar özellikle yaralıları tedavi etmek gibi hizmetlerde bulunduklarında bu verilir.',
 ['Tam pay verilmez','Mezhepte meşhur görüşe göre bahşiş de verilmez; bazı Mâlikîler imamın bahşiş verebileceğini söyler.'],['Bahşiş verilir','Tam pay verilmez.'],['Bahşiş verilir','Tam pay verilmez.'],
 'İbn Abbas’ın Necde’ye yazdığı mektupta kadınların savaşta yaralıları tedavi ettiği, kendilerine ganimetten bahşiş verildiği ama tam pay verilmediği bildirilir. Mezhepler bu konuda büyük ölçüde birleşir; fark bahşişin miktarı ve kaynağındadır.',
 [H('İbn Abbas: kadınlara ganimetten bahşiş verilirdi','يحذين من الغنيمه','Müslim.')],
 'Hükmün sebebi (sehm) savaşa katılmaya ehil olmaktır; ehliyeti eksik olanın hakkı da eksik olur.',
 [('kuduri','الرضخ'),('bidaye','النساء')]),
m('mushafsefer',SY,'Mushafla düşman ülkesine yolculuk','السفر بالمصحف إلى أرض العدو',
 'Güvenli büyük bir orduyla mushaf götürmekte sakınca yoktur. Düşmanın eline geçme korkusu bulunan küçük birliklerle (seriyye) ve tek başına götürmek mekruhtur.',
 ['Yasaktır','Hadisin zâhirine göre büyük ordu ile de götürülmez.'],['Korku varsa yasak','Düşmanın eline geçme ihtimali varsa götürülmez.'],['Korku varsa yasak','Güvenli ise caizdir.'],
 'Hadis yasağı belirtir; bir rivayette yasağın sebebi olarak düşmanın eline geçme korkusu da zikredilir. Sebebi dikkate alanlar güven durumunda caiz görmüş, zâhirini alanlar mutlak yasak saymıştır.',
 [H('“Kur’an ile düşman toprağına yolculuk etmeyi yasakladı”','ان يسافر بالقران الي ارض العدو','Buhârî, Müslim.')],
 'Hüküm illetiyle birlikte döner (el-hükmü yedûru ma‘a illetihî vücûden ve ademen).',
 [('kuduri','المصحف'),('bidaye','المصحف')]),
# ——— Yeminler ———
m('tahrimyemin',YM,'Helal bir şeyi kendine haram kılmak','تحريم الحلال',
 '“Bu yemek bana haram olsun” gibi helal bir şeyi kendine haram kılmak yemin sayılır. O şeyi yaparsa yemin kefareti gerekir. Eşine söylerse niyetine bakılır: talâk, zıhar ya da yemin (îlâ) olabilir.',
 ['Yemin değildir','Eş dışındaki şeyler için bir şey gerekmez; eşe söylenirse üç talâk sayılır.'],['Yemin değildir','Yiyecek ve benzerinde bir şey gerekmez; eşe söylenirse niyete göre talâk ya da zıhar, niyetsizse yemin kefareti.'],['Yemin kefareti gerekir','Eşe söylenirse zıhar olur.'],
 'Peygamber kendine bir şeyi haram kılınca âyet inmiş ve yeminlerin çözümünün (kefaret) meşru kılındığı bildirilmiştir. Hanefî ve Hanbelîler bunu, haram kılmanın yemin hükmünde olduğuna delil saymıştır.',
 [A('Tahrîm 66:1-2','66-1','“Ey Peygamber! Allah’ın sana helal kıldığını niçin kendine haram ediyorsun? … Allah size yeminlerinizin çözülmesini (kefaretle) meşru kılmıştır.”')],
 'Lafzın hakikati ile hükmî anlamı: haram kılmak sözlükte yemin değildir, fakat şer‘an yemin hükmüne bağlanmıştır.',
 [('kuduri','حرام'),('bidaye','حرام')]),
m('gayriallahyemin',YM,'Allah’tan başkası adına yemin etmek','الحلف بغير الله',
 'Babalar, peygamber, Kâbe gibi Allah’tan başkası adına yemin etmek yemin sayılmaz, mekruhtur; bozulmasıyla kefaret gerekmez. Talâk ve azat gibi şarta bağlanan sözler ise örfte “yemin” denmekle birlikte ayrı hükümlere tabidir.',
 ['Haram ya da mekruh','Yemin sayılmaz; kefaret gerekmez.'],['Mekruh','Yemin sayılmaz; kefaret gerekmez.'],['Haram','Yemin sayılmaz; bir rivayette Peygamber adına edilen yemin kefaret gerektirir.'],
 'Hadisler yasağı açıkça bildirir. İhtilaf, yasağın derecesinde (haram mı, mekruh mu) ve Peygamber adına yeminin istisna olup olmadığındadır. Hadisteki “şirk” ifadesi, âlimlerin çoğuna göre küçük şirk anlamındadır.',
 [H('“Allah sizi babalarınız adına yemin etmekten men eder”','ينهاكم ان تحلفوا بابايكم','Buhârî, Müslim.'),H('“Allah’tan başkası adına yemin eden şirk koşmuş olur”','من حلف بغير الله فقد','Tirmizî, Ebû Dâvûd.')],
 'Nehyin (yasak) tahrîm mi kerâhet mi ifade ettiği, karinelere göre belirlenir.',
 [('kuduri','بغير الله'),('bidaye','بغير الله')]),
# ——— Ferâiz ———
m('asabemaagayr',FR,'Kızlarla birlikte kız kardeşlerin asabe olması','الأخوات مع البنات عصبة',
 'Ölenin kızı ya da oğlunun kızı ile birlikte bulunan öz veya baba bir kız kardeşler asabe olur (asabe me‘a’l-gayr); paylar verildikten sonra kalanı alırlar.',
 ['Asabe olur','Hanefîlerle aynı.'],['Asabe olur','Hanefîlerle aynı.'],['Asabe olur','Hanefîlerle aynı.'],
 'Dört mezhep birleşir. İbn Abbas ise âyetteki “çocuğu yoksa” şartına dayanarak kızı varken kız kardeşe bir şey verilmeyeceğini söylemiştir. Cumhur, İbn Mes‘ûd’un Peygamber’in hükmüne dayanan rivayetini esas almıştır.',
 [H('“Kıza yarım, oğlun kızına üçte ikiye tamamlamak için altıda bir, kalanı kız kardeşe”','تكمله الثلثين','Buhârî.'),A('Nisâ 4:176','4-176','“Çocuğu olmayan bir kişi ölür de kız kardeşi bulunursa, bıraktığının yarısı onundur.”')],
 'Sünnetin âyetteki şartın mefhûmunu tahsis etmesi: “çocuğu yoksa” şartı pay (fard) için konmuştur, asabeliği engellemez.',
 [('kuduri','الأخوات'),('bidaye','الأخوات')]),
m('ceddepay',FR,'Ninenin payı ve babayla birlikte mirası','ميراث الجدة',
 'Nine ya da nineler altıda bir alır; birden fazla ise bu altıda biri paylaşırlar. Anne, bütün nineleri düşürür. Baba da kendi annesini (babaanne) düşürür.',
 ['Baba, babaanneyi düşürür','Hanefîlerle aynı.'],['Baba, babaanneyi düşürür','Hanefîlerle aynı.'],['Babaanne babayla mirasçı olur','Babası hayattayken de altıda biri alır.'],
 'Ninenin altıda bir alacağı, Hz. Ebû Bekir zamanında Mugîre ve Muhammed b. Mesleme’nin şahitliğiyle bildirilen sünnete dayanır. Babaannenin babayla mirasçı olup olmadığı ise İbn Mes‘ûd’dan gelen bir rivayete dayanır; cumhur, aracı olan kişinin varken onun aracılığıyla mirasçı olanı düşürdüğü kuralını uygulamıştır.',
 [H('Peygamber nineye altıda bir verdi','اعطاها السدس','Ebû Dâvûd, Tirmizî.')],
 'Bir kişi aracılığıyla mirasçı olan, o aracı varken mirasçı olmaz (men edlâ bi-şahsın lâ yerisü ma‘ahû).',
 [('kuduri','الجدة'),('bidaye','الجدة')]),
m('garka',FR,'Birlikte ölenlerin (boğulma, göçük) mirası','ميراث الغرقى والهدمى',
 'Boğulma, göçük, yangın gibi bir olayda ölen ve hangisinin önce öldüğü bilinmeyen yakınlar birbirine mirasçı olmaz. Her birinin malı kendi hayattaki mirasçılarına geçer.',
 ['Birbirine mirasçı olmazlar','Hanefîlerle aynı.'],['Birbirine mirasçı olmazlar','Hanefîlerle aynı.'],['Birbirine mirasçı olurlar','Her biri diğerinin, ondan önce sahip olduğu malına mirasçı olur; yeni miras ettiği maldan olmaz.'],
 'Mirasçının, miras bırakanın ölümünden sonra hayatta olduğunun kesin bilinmesi şarttır. Şüphe ile miras ispat edilmez. Hanbelîler ise Hz. Ömer ve Ali’den gelen rivayetleri esas alarak her birini diğerinden sonra ölmüş saymıştır.',
 [A('Nisâ 4:11','4-11','“Allah size çocuklarınız hakkında şunu emreder: Erkeğe iki kadının payı kadar vardır.”')],
 'Şüphe ile hak sabit olmaz; miras için mirasçının hayatının kesin bilinmesi şarttır.',
 [('kuduri','الغرقى'),('bidaye','الغرقى')]),
m('annehacb',FR,'Annenin payının kardeşlerle altıda bire düşmesi','حجب الأم بالإخوة',
 'Ölenin iki ya da daha fazla kardeşi (erkek veya kız, öz, baba bir ya da ana bir) varsa anne üçte bir yerine altıda bir alır; kardeşler mirastan pay almasalar bile (baba onları düşürse bile) anneyi düşürürler.',
 ['İki kardeş yeterli','Hanefîlerle aynı.'],['İki kardeş yeterli','Hanefîlerle aynı.'],['İki kardeş yeterli','Hanefîlerle aynı.'],
 'Âyette “kardeşler” çoğul gelmiştir. İbn Abbas en az üç kardeş gerektiğini söylemiştir. Sahâbenin çoğunluğu ise mirasta ikinin çoğul hükmünde olduğunu kabul etmiştir; dört mezhep de bunu benimsemiştir.',
 [A('Nisâ 4:11','4-11','“Ölenin kardeşleri varsa, annesine altıda bir düşer.”')],
 'Mirasta ve vasiyette ikinin çoğul hükmünde olması; çoğulun en az sayısı tartışması.',
 [('kuduri','الإخوة'),('bidaye','الأم')]),
# ——— Kurban ve yiyecekler ———
m('kurbandericasap',KB,'Kurbanın etinden, derisinden kasaba ücret vermek ve satmak','بيع جلد الأضحية وأجر الجزار',
 'Kurbanın eti, derisi ve diğer parçalarından hiçbir şey kasaba ücret olarak verilemez; satılıp parası kişinin kendisine harcanamaz. Derisi tasadduk edilir ya da kullanılır; kalıcı bir eşya ile değiştirilebilir. Etin üçte birinin tasadduk edilmesi müstehaptır.',
 ['Satılamaz','Ücret olarak da verilemez; deriyle değiş tokuş da caiz değildir.'],['Satılamaz','Ücret olarak verilemez.'],['Satılamaz','Ücret olarak verilemez; bir rivayette deriyi satıp parasını sadaka vermek caizdir.'],
 'Hz. Ali, Peygamber’in kendisine kurbanların etini, derisini ve çullarını dağıtmasını, kasaba bunlardan ücret vermemesini emrettiğini bildirir. Mezhepler kasaba ücret verme yasağında birleşir; derinin başka bir eşyayla değiştirilmesinde ayrılır.',
 [H('Hz. Ali: “Kasaba ondan bir şey vermememi emretti”','ان لا اعطي الجزار منها','Buhârî, Müslim.')],
 'Kurbana tahsis edilen şey Allah’a yakınlık için ayrılmıştır; ondan bedel almak bu tahsisi bozar.',
 [('kuduri','الجزار'),('bidaye','جلود')]),
m('keler',YY,'Keler (dabb) eti','أكل الضب',
 'Keler eti mekruhtur (tahrîmen). Peygamber onu yememiştir; bir rivayette Hz. Âişe’ye, kendisinin yemediği bu eti bir yoksula da yedirmemesini söylediği nakledilir.',
 ['Helaldir','Peygamber’in sofrasında yenmiştir.'],['Helaldir','Peygamber yememiş fakat yasaklamamıştır.'],['Helaldir','Hâlid b. Velîd onu Peygamber’in yanında yemiştir.'],
 'Hâlid b. Velîd’in Peygamber’in yanında keler yediği, Peygamber’in ise “Benim kavmimin toprağında yoktu, ondan tiksiniyorum” dediği sahih hadistedir. Cumhur bunu helal olduğuna delil saymıştır. Hanefîler ise yasak bildiren diğer rivayetleri ve hayvanın habâisten sayılmasını esas almıştır.',
 [H('“Kavmimin toprağında yoktu, ondan tiksiniyorum”','فاجدني اعافه','Buhârî, Müslim.'),A('A‘râf 7:157','7-157','“Onlara temiz şeyleri helal, pis şeyleri haram kılar.”')],
 'Mübah kılan ile yasaklayan rivayetler çatıştığında Hanefîler ihtiyaten yasaklayanı tercih eder.',
 [('kuduri','الضب'),('bidaye','الضب')]),
m('ehliesek',YY,'Ehlî eşek eti','لحوم الحمر الأهلية',
 'Evcil (ehlî) eşeğin eti haramdır. Yaban eşeğinin eti ise helaldir.',
 ['Haram','Meşhur görüş; bir rivayette mekruh.'],['Haram','Hanefîlerle aynı.'],['Haram','Hanefîlerle aynı.'],
 'Peygamber Hayber günü ehlî eşeklerin etini yasaklamıştır. İbn Abbas yasağın, onların yük hayvanı olarak korunması için konmuş geçici bir tedbir olabileceğini söylemiştir; İmam Mâlik’ten gelen kerâhet rivayeti buna dayanır. Cumhur yasağı kalıcı bir tahrim saymıştır.',
 [H('Hayber günü ehlî eşeklerin etini yasakladı','لحوم الحمر الاهليه','Buhârî, Müslim.')],
 'Yasağın illeti tartışması: zâtî bir haramlık mı, geçici bir maslahat mı? Geçici maslahat illeti kalkınca hüküm de kalkar.',
 [('kuduri','الحمر'),('bidaye','الحمر')]),
m('cekirge',YY,'Çekirge eti','أكل الجراد',
 'Çekirge kesilmeden helaldir; kendiliğinden ölmüşü de yenir.',
 ['Helaldir','Ancak öldürülmesi (başının koparılması, kaynatılması gibi) kesim yerine geçer; kendiliğinden ölmüşü yenmez.'],['Helaldir','Kendiliğinden ölmüşü de yenir.'],['Helaldir','Kendiliğinden ölmüşü de yenir.'],
 'Sahâbe Peygamber’le birlikte gazvelerde çekirge yemiştir. Ayrıca “Bize iki ölü helal kılındı: balık ve çekirge” rivayeti vardır. Mâlikîler çekirgeyi kara hayvanı saydıkları için bir tür kesim (tezkiye) şart koşmuştur.',
 [H('“Peygamber’le birlikte gazvelere çıktık, çekirge yiyorduk”','ناكل الجراد','Buhârî, Müslim.')],
 'Âmm olan “ölü hayvan haramdır” hükmünün sünnetle tahsisi.',
 [('kuduri','الجراد'),('bidaye','الجراد')]),
# ——— Hadler ———
m('ikrarrucu',HD,'Had gerektiren suçun ikrarından dönmek','الرجوع عن الإقرار في الحدود',
 'Zina, hırsızlık, içki gibi Allah hakkı olan bir suçu ikrar eden kişi, ceza uygulanmadan önce ya da uygulanırken ikrarından dönerse had düşer. Hırsızlıkta malı tazmin etmesi gerekir; çünkü o kul hakkıdır.',
 ['Şüpheli bir sebeple dönerse düşer','Sebepsiz dönmede iki rivayet vardır; meşhur olanı düşmesidir.'],['Düşer','Hanefîlerle aynı.'],['Düşer','Hanefîlerle aynı.'],
 'Mâiz recmedilirken kaçmış, Peygamber “Onu bıraksaydınız ya!” buyurmuştur. Bu, dönmenin cezayı düşürdüğüne delil sayılmıştır. Kul haklarında ise ikrardan dönmek kabul edilmez.',
 [H('Mâiz hakkında: “Onu bıraksaydınız ya!”','فهلا تركتموه','Ebû Dâvûd, Tirmizî.')],
 'Hadler şüphelerle düşer; Allah hakkı affa dayanır, kul hakkı ise ikrarla kesinleşir.',
 [('kuduri','رجع'),('bidaye','الرجوع')]),
]
